/* @lc app=leetcode id=2493 lang=kotlin */ class Solution { fun bfs(g: Map<Int, List<Int>>, s: Int, n: Int): Triple<Int, Int, Boolean> = IntArray(n + 1) { -1 }.let { d -> generateSequence(listOf(s).onEach { d[it] = 0 }) { f -> f.flatMap { u -> g[u].orEmpty().filter { d[it] == -1 }.distinct().onEach { v -> d[v] = d[u] + 1 } }.takeIf { it.isNotEmpty() } }.toList().let { lv -> lv.flatten().let { all -> Triple(all.min(), lv.size, all.any { a -> g[a].orEmpty().any { b -> d[b] == d[a] } }) } } } fun magnificentSets(n: Int, edges: Array<IntArray>): Int = edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> (1..n).map { bfs(g, it, n) }.let { r -> if (r.any { it.third }) -1 else r.groupBy({ it.first }, { it.second }).values.sumOf { it.max() } } } }